-- Hidden search keywords (aliases) per activity, in German and English.
--
-- The HETUS activity names are sometimes old-fashioned ("Waschen und
-- Anziehen", "Konsolenspiele"), so users searching for everyday words like
-- "duschen" or "gamen" found nothing. These keywords are never shown in the
-- UI; the activity search in ActivitySelector.tsx matches them in addition to
-- the visible name (keywords_de for the German UI, keywords_en for English).
--
-- Rows are matched by the language-neutral HETUS `code`, not by id or name.
-- Generated from a single keyword list (also exported to Excel for review);
-- edit keywords by re-running an UPDATE for the affected code.

ALTER TABLE public.activity
  ADD COLUMN IF NOT EXISTS keywords_de text[] NOT NULL DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS keywords_en text[] NOT NULL DEFAULT '{}';

UPDATE public.activity SET keywords_de = ARRAY['schlafen', 'schlaf', 'nickerchen', 'mittagsschlaf', 'dösen', 'pennen', 'bett', 'ins bett gehen', 'nachtruhe']::text[], keywords_en = ARRAY['sleep', 'sleeping', 'nap', 'napping', 'bed', 'bedtime', 'snooze']::text[] WHERE code = '011';
